class Task:
    def __init__(self, C_i, T_i, D_i, S_i):
        self.C_i = C_i
        self.T_i = T_i
        self.D_i = D_i
        self.S_i = S_i

class SegmentedTask:
    def __init__(self, segments):
        # segments is a list: [C_i_1, S_i_1, C_i_2, ...]
        self.pattern = segments
        self.C_i = sum(s for i, s in enumerate(segments) if i % 2 == 0)
        self.S_i = sum(s for i, s in enumerate(segments) if i % 2 != 0)

def calculate_B_k(tau_k, hp_tasks):
    B_k = tau_k.S_i
    for tau_i in hp_tasks:
        B_k += min(tau_i.S_i, tau_i.C_i)
    return B_k

def test_theorem_1(tau_k, hp_tasks):
    for t in range(1, tau_k.D_i + 1):
        demand = tau_k.S_i + tau_k.C_i
        for tau_i in hp_tasks:
            demand += ceil(t / tau_i.T_i) * (tau_i.C_i + tau_i.S_i)
        if demand <= t:
            return True
    return False

def test_theorem_3(tau_k, hp_tasks):
    B_k = calculate_B_k(tau_k, hp_tasks)
    for t in range(1, tau_k.D_i + 1):
        demand = tau_k.C_i + B_k
        for tau_i in hp_tasks:
            demand += ceil(t / tau_i.T_i) * tau_i.C_i
        if demand <= t:
            return True
    return False

def test_theorem_4(tau_k, hp_tasks):
    for t in range(1, tau_k.D_i + 1):
        demand = tau_k.S_i + tau_k.C_i
        for tau_i in hp_tasks:
            jitter_i = tau_i.D_i - tau_i.C_i
            demand += ceil((t + jitter_i) / tau_i.T_i) * tau_i.C_i
        if demand <= t:
            return True
    return False

def test_theorem_5(tau_k, hp_tasks, y_vector):
    # hp_tasks must be sorted by priority (1 is highest)
    for t in range(1, tau_k.D_i + 1):
        demand = tau_k.S_i + tau_k.C_i
        for i, tau_i in enumerate(hp_tasks):
            # Q_y_i is sum of S_j * y_j for j from i to k-1
            Q_y_i = sum(hp_tasks[j].S_i * y_vector[j] for j in range(i, len(hp_tasks)))
            jitter_term = (1 - y_vector[i]) * (tau_i.D_i - tau_i.C_i)
            demand += ceil((t + Q_y_i + jitter_term) / tau_i.T_i) * tau_i.C_i
        if demand <= t:
            return True
    return False

def dbf_FRD(t, tau_i, D_i_1):
    # Pattern 1
    d1 = floor((t + tau_i.T_i - D_i_1) / tau_i.T_i) * tau_i.C_i_1 + floor(t / tau_i.T_i) * tau_i.C_i_2
    # Pattern 2
    d2 = floor((t + D_i_1 + tau_i.S_i) / tau_i.T_i) * tau_i.C_i_2 + floor((t + tau_i.S_i) / tau_i.T_i) * tau_i.C_i_1
    return max(d1, d2)

def is_frd_schedulable(task_set, deadlines_dict):
    # deadlines_dict maps task to its D_i_1
    # In practice, t is checked up to a hyperperiod or busy period
    for t in range(1, max_t):
        total_demand = sum(dbf_FRD(t, tau_i, deadlines_dict[tau_i]) for tau_i in task_set)
        if total_demand > t:
            return False
    return True
